'use strict';
const CharmCandidates=(()=>{
 const key=SavedBuilds.charmKey,panels=new Set(),filtersById=new Map();let wishlistSearch='',wishlistFilter='all';
 const owned=c=>!!c&&CandidateContext.get().records.some(r=>key(r)===key(c));
 const wished=c=>!!c&&CharmWishlistStore.get().some(r=>key(r)===key(c));
 const text=(p,tag,value)=>{const e=document.createElement(tag);e.textContent=value;p.append(e);return e;};
 const label=c=>c?[...(c.name?[c.name]:[]),c.skills.map(s=>`${s.name}:${s.level}`).join('  /  '),...(c.armorSlots.length?['Lv'+c.armorSlots.join('-')]:[]),...(c.weaponSlots.length?['⚔ Lv'+c.weaponSlots.join('-')]:[])].filter(Boolean).join('   |   '):'호석 사용 안 함';
 function toggle(c){if(!c)return false;return CharmWishlistStore.set(wished(c)?CharmWishlistStore.get().filter(r=>key(r)!==key(c)):[...CharmWishlistStore.get(),c]);}
 function panel(candidates,getActive,onChange,id='',total=candidates.length){
  const root=document.createElement('section');root.className='build-charm-variants';root.setAttribute('aria-label',`호석 후보 ${candidates.length}개`);const more=document.createElement('details');more.className='charm-options';const moreSummary=text(more,'summary','⋯');moreSummary.setAttribute('aria-label','호석 후보 필터·찜 설정');const menu=document.createElement('div');menu.className='charm-options-menu';more.append(menu);
  const filters=text(root,'label',''),filter=document.createElement('select');filter.setAttribute('aria-label','호석 후보 필터');for(const[v,l]of [['all','전체'],['owned','보유만'],['wish','찜만'],['missing','미보유만']]){const o=text(filter,'option',l);o.value=v;}filter.value=filtersById.get(id)||'all';filters.className='charm-inline-filter';filters.append(filter);
  const choice=text(root,'div',''),select=document.createElement('select');choice.className='charm-choice';select.hidden=true;select.tabIndex=-1;select.setAttribute('aria-hidden','true');select.className='build-charm-select';select.setAttribute('aria-label','호석 후보 선택');choice.append(select);
  const trigger=text(choice,'button','');trigger.type='button';trigger.className='charm-choice-toggle';trigger.setAttribute('role','combobox');trigger.setAttribute('aria-label','호석 후보 선택');trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');
  const popup=text(choice,'div','');popup.className='charm-choice-popup';popup.hidden=true;const columns=text(popup,'div','');columns.className='charm-choice-columns';for(const heading of ['스킬','슬롯','무기 슬롯'])text(columns,'span',heading);const listbox=text(popup,'div','');listbox.className='charm-choice-list';listbox.id='charm-list-'+crypto.randomUUID();listbox.setAttribute('role','listbox');listbox.setAttribute('aria-label','호석 후보');trigger.setAttribute('aria-controls',listbox.id);const count=text(root,'p','');count.className='charm-candidate-count';count.setAttribute('role','status');let cursor=0,visible=[];
  function close(){popup.hidden=true;trigger.setAttribute('aria-expanded','false');trigger.removeAttribute('aria-activedescendant');}
  function highlight(){const options=[...listbox.children];options.forEach((o,i)=>o.classList.toggle('is-highlighted',i===cursor));if(options[cursor]){trigger.setAttribute('aria-activedescendant',options[cursor].id);options[cursor].scrollIntoView({block:'nearest'});}}
  function open(){for(const p of panels)if(p.root!==root)p.close?.();if(trigger.disabled)return;popup.hidden=false;popup.style.position='fixed';const rect=trigger.getBoundingClientRect(),width=popup.getBoundingClientRect().width,height=popup.getBoundingClientRect().height;popup.style.right='auto';popup.style.left=Math.max(12,Math.min(innerWidth-width-12,rect.right-width))+'px';popup.style.top=Math.max(12,Math.min(innerHeight-height-12,rect.bottom+height+3>innerHeight&&rect.top>height?rect.top-height-3:rect.bottom+3))+'px';trigger.setAttribute('aria-expanded','true');cursor=Math.max(0,visible.indexOf(getActive()));highlight();}
  function choose(n){close();trigger.focus({preventScroll:true});select.value=String(n);select.dispatchEvent(new Event('change'));}
  trigger.addEventListener('click',()=>popup.hidden?open():close());
  trigger.addEventListener('keydown',event=>{const k=event.key;if(['ArrowDown','ArrowUp','Home','End','Escape','Enter',' '].includes(k)){event.preventDefault();if(k==='Escape'){close();return;}if(popup.hidden){open();return;}if(k==='Enter'||k===' '){if(visible[cursor]!==undefined)choose(visible[cursor]);return;}cursor=k==='Home'?0:k==='End'?visible.length-1:Math.max(0,Math.min(visible.length-1,cursor+(k==='ArrowDown'?1:-1)));highlight();}else if(k==='Tab')close();});
  root.addEventListener('focusout',event=>{if(!root.contains(event.relatedTarget))close();});

  const star=text(root,'button','찜하기');star.type='button';star.className='charm-wish-button';const status=text(root,'p','');status.className='charm-candidate-status';status.setAttribute('role','status');
  const refresh=()=>{const active=getActive(),c=candidates[active]?.charm;select.replaceChildren();listbox.replaceChildren();visible=[];candidates.forEach((b,n)=>{const c=b.charm,isOwned=owned(c),isWish=wished(c);if(filter.value==='owned'&&!isOwned||filter.value==='wish'&&!isWish||filter.value==='missing'&&(!c||isOwned))return;const o=text(select,'option',`${isWish?'[찜]  ':''}${label(c)}`);o.value=n;visible.push(n);const item=text(listbox,'button','');item.type='button';item.tabIndex=-1;item.id=listbox.id+'-'+n;item.className='charm-choice-option';item.setAttribute('role','option');item.setAttribute('aria-selected',String(n===active));text(item,'span',`${isWish?'★ ':''}${c?(c.name?c.name+' | ':'')+c.skills.map(s=>s.name+':'+s.level).join(' / '):'호석 사용 안 함'}`).className='charm-option-skills';text(item,'span',c?.armorSlots.length?'Lv'+c.armorSlots.join('-'):'—').className='charm-option-slots';const weapon=text(item,'span',c?.weaponSlots.length?'⚔ Lv'+c.weaponSlots.join('-'):'—');weapon.className='charm-option-weapon';item.addEventListener('click',()=>choose(n));});select.title=label(c);const visibleCount=select.options.length,empty=!visibleCount;if(empty){const placeholder=text(select,'option','조건에 맞는 후보 없음');placeholder.value='';}select.value=empty?'':String(active);select.disabled=empty;trigger.textContent=empty?'조건에 맞는 후보 없음':label(c);trigger.title=label(c);trigger.disabled=empty;count.textContent=`전체 후보 ${total}개${visibleCount!==total?' · 표시 '+visibleCount+'개':''}`;if(empty)close();star.disabled=!c;star.textContent=wished(c)?'★':'☆';star.setAttribute('aria-label',wished(c)?'찜 해제':'찜하기');star.title=wished(c)?'찜 해제':'찜하기';star.setAttribute('aria-pressed',String(wished(c)));status.textContent=`${visibleCount} / ${candidates.length}개 표시${!visibleCount?' · 조건에 맞는 후보가 없습니다.':select.value===''?' · 현재 선택한 호석은 필터에서 제외되었습니다.':''}`;};
  filter.addEventListener('change',()=>{close();if(id)filtersById.set(id,filter.value);refresh();});select.addEventListener('change',()=>{onChange(Number(select.value));refresh();});star.addEventListener('click',()=>{close();if(!toggle(candidates[getActive()]?.charm)){status.classList.add('is-error');status.textContent='찜목록을 저장하지 못했습니다. 보유 호석 페이지의 저장 상태를 확인하세요.';}else{status.classList.remove('is-error');refresh();}});
  root.insertBefore(choice,filters);root.append(more);panels.add({root,refresh,close});refresh();return root;
 }
 function renderWishlist(root){root.replaceChildren();text(root,'h2',`호석 찜목록 · ${CharmWishlistStore.get().length}개`);const controls=document.createElement('div');controls.className='charm-wishlist-controls';const search=text(controls,'label','스킬·슬롯 검색'),input=document.createElement('input');input.type='search';input.placeholder='예: 납도술';input.value=wishlistSearch;search.append(input);const state=text(controls,'label','보유 여부'),filter=document.createElement('select');for(const[v,l]of [['all','전체'],['owned','보유만'],['missing','미보유만']]){const o=text(filter,'option',l);o.value=v;}filter.value=wishlistFilter;state.append(filter);root.append(controls);const list=document.createElement('div');list.className='charm-wishlist-list';root.append(list);
  function refresh(){list.replaceChildren();const items=CharmWishlistStore.get().filter(c=>(filter.value==='all'||owned(c)===(filter.value==='owned'))&&label(c).toLocaleLowerCase().includes(input.value.trim().toLocaleLowerCase()));if(!items.length)text(list,'p','표시할 찜 호석이 없습니다. 검색 결과나 저장 세팅의 후보에서 찜하기를 누르세요.');for(const c of items){const row=document.createElement('div');row.className='charm-wishlist-row';text(row,'span',`${owned(c)?'보유':'미보유'} · ${label(c)}`);const b=text(row,'button','찜 해제');b.type='button';b.addEventListener('click',()=>{toggle(c);});list.append(row);}}
  input.addEventListener('input',()=>{wishlistSearch=input.value;refresh();});filter.addEventListener('change',()=>{wishlistFilter=filter.value;refresh();});refresh();
 }
 window.addEventListener('resize',()=>{for(const p of panels)p.close?.();});document.addEventListener('scroll',event=>{if(event.target.closest?.('.charm-choice-list'))return;for(const p of panels)p.close?.();},true);
 document.addEventListener('click',event=>{for(const p of panels){if(!p.root.isConnected)panels.delete(p);else if(!p.root.contains(event.target))p.close?.();}});
 document.addEventListener('inventory-state-changed',()=>{for(const p of panels){if(!p.root.isConnected)panels.delete(p);else p.refresh();}});
 return {owned,wished,panel,renderWishlist};
})();
